Test("quotes come back in input order", async () =>
{
    async Task<decimal> Fetch(string s, CancellationToken ct) { await Task.Delay(s == "AAA" ? 60 : 10, ct); return s.Length * 10m; }
    var quotes = await GetQuotesAsync(new[] { "AAA", "B", "CC" }, Fetch, CancellationToken.None);
    Eq(quotes.Select(q => q.Symbol).ToList(), new[] { "AAA", "B", "CC" });
    Eq(quotes.Select(q => q.Price).ToList(), new[] { 30m, 10m, 20m });
});

Test("the fetches run concurrently", async () =>
{
    var active = 0;
    var peak = 0;
    async Task<decimal> Fetch(string s, CancellationToken ct)
    {
        var now = Interlocked.Increment(ref active);
        lock (typeof(Quote)) peak = Math.Max(peak, now);
        await Task.Delay(50, ct);
        Interlocked.Decrement(ref active);
        return 1m;
    }
    await GetQuotesAsync(new[] { "A", "B", "C", "D" }, Fetch, CancellationToken.None);
    Eq(peak, 4);
});

Test("the token reaches every fetch", async () =>
{
    using var cts = new CancellationTokenSource();
    var seen = new List<CancellationToken>();
    Task<decimal> Fetch(string s, CancellationToken ct) { lock (seen) seen.Add(ct); return Task.FromResult(1m); }
    await GetQuotesAsync(new[] { "A", "B" }, Fetch, cts.Token);
    Ok(seen.Count == 2 && seen.All(t => t == cts.Token), "every fetch must receive the caller's token");
});

Test("cancellation ends the call with OperationCanceledException", async () =>
{
    using var cts = new CancellationTokenSource(30);
    async Task<decimal> Slow(string s, CancellationToken ct) { await Task.Delay(5000, ct); return 1m; }
    await ThrowsAsync<OperationCanceledException>(() => GetQuotesAsync(new[] { "A", "B" }, Slow, cts.Token));
});

Test("no symbols, no calls (boundary)", async () =>
{
    var calls = 0;
    Task<decimal> Fetch(string s, CancellationToken ct) { calls++; return Task.FromResult(1m); }
    var quotes = await GetQuotesAsync(Array.Empty<string>(), Fetch, CancellationToken.None);
    Eq(quotes.Count, 0);
    Eq(calls, 0);
});

